    public static int oddLengthSum(List<Integer> arr) {
        int sum = 0, l = arr.size();
        for (int i = 0; i < l; i++) {
            sum += Math.floor(((i + 1) * (l - i) + 1) / 2) * arr.get(i);
        }
        return sum;
    }
}

